def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        return min(budget, 21.0)

    prev_bids = []
    desperate_count = 0
    broke_count = 0
    error_count = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) < DAILY_SALARY * 0.6:
            broke_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('error'):
            error_count += 1
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)
        status = prev.get('status')
        if status in ('thirsty', 'critical', 'failed'):
            desperate_count += 1

    slots_est = max(1, int(supply // WATER_REQ))
    pressure = len(alive_opponents) + 1 - slots_est

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 0.0
        avg_prev = 0.0

    if hp <= 2 or no_water_days >= 2:
        target = max(63.0, highest_prev + 2.0)
    elif hp <= 4 or no_water_days >= 1:
        target = max(52.0, avg_prev + 3.0, highest_prev * 0.92)
    else:
        if pressure <= 0:
            target = 18.0 + 2.0 * max(0, desperate_count - broke_count)
        elif pressure == 1:
            target = max(28.0, avg_prev + 1.5)
        else:
            target = max(36.0, avg_prev + 3.0, highest_prev * 0.82)

    if error_count > 0:
        target -= 4.0
    if broke_count >= len(alive_opponents) / 2.0:
        target -= 5.0
    if desperate_count > len(alive_opponents) / 2.0:
        target += 4.0

    day = day_context['day']
    if day >= 8 and hp <= 5:
        target += 6.0

    target = max(0.0, min(float(budget), target))
    return target

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # Baseline bid: aim for at least one unit of water requirement, scaled by supply.
    # Since bidding is simultaneous and hidden, use a conservative fraction of budget.
    budget = float(my_status['budget'])
    hp = float(my_status['hp'])
    no_water_days = int(my_status['no_water_days'])

    # Extract yesterday bids from previous_trace for immediate reaction.
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    # If opponents were aggressive yesterday, we counter.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # Aggression threshold relative to our daily salary.
        if highest_prev_bid >= 0.85 * DAILY_SALARY:
            # We must protect hp if low; otherwise still bid decisively but not all-in.
            if hp <= 2 or no_water_days >= 2:
                target = 0.95 * DAILY_SALARY
            else:
                target = 0.65 * DAILY_SALARY
        else:
            # Moderate response: slightly above their likely effective level.
            # Add a small premium to win ties.
            target = max(0.45 * DAILY_SALARY, highest_prev_bid + 5.0)
    else:
        # No signal: bid based on our condition.
        if hp <= 2 or no_water_days >= 2:
            target = 0.9 * DAILY_SALARY
        elif hp <= 3:
            target = 0.65 * DAILY_SALARY
        else:
            target = 0.55 * DAILY_SALARY

    # Adjust for current supply: lower supply -> more competitive -> bid higher.
    # Normalize supply into [0,1] between MIN_SUPPLY and MAX_SUPPLY.
    if MAX_SUPPLY != MIN_SUPPLY:
        norm = (supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
    else:
        norm = 0.5
    # When norm is low (scarce), increase bid.
    scarcity_factor = 1.0 + (0.5 * (1.0 - max(0.0, min(1.0, norm))))
    target *= scarcity_factor

    # Convert target into a final bid capped by budget.
    bid = min(budget, target)

    # Ensure bid is non-negative.
    if bid < 0:
        bid = 0.0

    return float(bid)
